// Generates migrations/0002_seed.sql from src/lib/content/seed.ts.
// Run from app/: `bun scripts/gen-seed.ts`. INSERT OR IGNORE keeps it safe to
// re-apply: rows the owner has edited in /admin are never overwritten.
import { writeFileSync } from "node:fs";
import { SEED_CATEGORIES, SEED_POSTS } from "../src/lib/content/seed";

const q = (value: string | number | boolean) => {
  if (typeof value === "number") return String(value);
  if (typeof value === "boolean") return value ? "1" : "0";
  return `'${value.replace(/'/g, "''")}'`;
};

const lines: string[] = [
  "-- Generated by scripts/gen-seed.ts from src/lib/content/seed.ts. Do not edit by hand.",
  "-- INSERT OR IGNORE: never overwrites content edited in /admin.",
  "",
];

for (const c of SEED_CATEGORIES) {
  lines.push(
    `INSERT OR IGNORE INTO menu_categories (slug, title, subtitle, story, mood, image, image_alt, icon, sort) VALUES (${[
      c.slug,
      c.title,
      c.subtitle,
      c.story,
      c.mood,
      c.image,
      c.imageAlt,
      c.icon,
      c.sort,
    ]
      .map(q)
      .join(", ")});`,
  );
}
lines.push("");
for (const p of SEED_POSTS) {
  lines.push(
    `INSERT OR IGNORE INTO journal_posts (id, slug, title, category, excerpt, cover, cover_alt, body, author, published_at, published) VALUES (${[
      p.id,
      p.slug,
      p.title,
      p.category,
      p.excerpt,
      p.cover,
      p.coverAlt,
      p.body,
      p.author,
      p.publishedAt,
      p.published,
    ]
      .map(q)
      .join(", ")});`,
  );
}

writeFileSync(new URL("../migrations/0002_seed.sql", import.meta.url), `${lines.join("\n")}\n`);
console.log(`wrote ${SEED_CATEGORIES.length} categories, ${SEED_POSTS.length} posts`);
